"""Report the stopped production checkpoint, retaining complete evidence."""
import collections,csv,hashlib,html,json,re
from pathlib import Path
R=Path(__file__).resolve().parents[1];O=R/'docs/revisao-visual-unificado/producao-20261120'
load=lambda name:json.loads((O/name).read_bytes())
before=load('inventory.json');after=load('inventory-after-stop.json');plan=load('deployment-plan.json');backup=load('backup-final.json');frozen=load('frozen.json');rehearsal=load('rollback-rehearsal.json');audit=load('migration-audit.json');live=load('checkpoint-live-evidence.json')
assert before['files']==after['files'] and before['master_policy']==after['master_policy'] and after['version']=='1.4.6'
assert before['nginx']==after['nginx']
bc={s['unit']:s['config_files'] for s in before['services']};ac={s['unit']:s['config_files'] for s in after['services']};assert bc==ac
assert hashlib.sha256((O/'candidate.tgz').read_bytes()).hexdigest()==frozen['archive_sha256']
e=lambda v:html.escape(str(v))
def table(headers,rows):return '<table><thead><tr>'+''.join('<th>'+e(c)+'</th>' for c in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table>'
def a(file,label):return '<a href="'+e(file)+'">'+e(label)+'</a>'
unit_names={1:'Campinas',2:'Pederneiras',3:'Ribeirão',4:'Noroeste'}
arm_rows=[(unit_names[r['unidade_id']],str(r['enabled']).lower(),'false','Não alterado') for r in live['production_armacao']]
groups=collections.Counter()
for row in before['cluster']['sessions']:
 cgroup=row.get('client_cgroup','');match=re.search(r'([^/]+\.service)',cgroup);svc=match.group(1) if match else ('Auditoria SQL / conexão local' if row['client_port']==-1 else 'Sem processo local identificado')
 groups[(svc,row['datname'] or '',row['usename'] or '',row['application_name'] or '',row['state'] or row['backend_type'])]+=1
connection_rows=[(*key,n) for key,n in sorted(groups.items(),key=lambda x:(-x[1],x[0]))]
with (O/'connections-by-service.csv').open('w',encoding='utf-8-sig',newline='') as f:
 writer=csv.writer(f);writer.writerow(['serviço','banco','usuário','application_name','estado','conexões']);writer.writerows(connection_rows)
with (O/'migration-status.csv').open('w',encoding='utf-8-sig',newline='') as f:
 writer=csv.writer(f);writer.writerow(['área','referência','revisão','estado em produção','objetos conferidos']);writer.writerows((r['area'],r['reference'],r['revision'],r['status'],len(r['evidence'])) for r in audit)
audit_rows=[(r['area'],r['revision'],r['status'],len(r['evidence'])) for r in audit]
scp='scp vps-concrefer:'+backup['bundle']+' .'
rollback='ssh vps-concrefer "'+backup['directory']+'/rollback.sh"'
grant_rows=[('Central','alex','MASTER_USER_IDS','Já presente; sem concessão'),('PCP','alex ↔ usuário 145','ADMIN; vínculo central 121','Preservado'),('Logística','alex','MASTERS nas duas camadas','Já presente; sem patch'),('GED','alex ↔ 2b103d6e-4287-4bd4-b53e-e122899f323d','ADMIN_MASTER; vínculo ativo','Identidade nativa preservada'),('Suprimentos','alex','ADMIN e APROVADOR, unidade 1','Papéis nativos preservados'),('Dosagem','unificado-alex@concretrack.local','admin; unidades *','Já presente'),('user-alex','Identidade de teste','Central inativa/excluída','Nenhuma concessão; fora das listas master da candidata')]
checks=[('Fase 0 — candidata 1.4.30','Concluída: gate 7/7; 9 perfis; 72 casos de módulo; 48 consultas de busca'),('Congelamento','Tag local candidata-producao-1.4.30; commit 701733b; sem push'),('Inventário','Concluído; 34 referências estruturais presentes; 19 do PCP comprovadas'),('Backups','6 dumps com pg_restore --list e leitura integral; arquivos/configurações preservados'),('Ensaio de reversão na 18446','1.4.30 → 1.4.29 → 1.4.30; gate 7/7 nas duas versões; cerca de '+str(rehearsal['total_duration_seconds_approx'])+' s incluindo verificações'),('Service worker de produção antes da publicação','1.4.6 real ativo em perfil persistente Chrome; cache com 21 entradas; sem senha ou alteração de conta'),('Checkpoint','REPROVADO: Armação enabled:true; CQ com configuração diferente entre ambientes'),('Fases 3, 4 e 5 de publicação','Não executadas: não houve publicação, concessão, migração ou reinício'),('Provas posteriores solicitadas','Perfis na versão nova em produção, 8 módulos de alex, impressão/PDF, integrações, upgrade 1.4.6 → 1.4.30 e observação de 30 minutos: pendentes, pois a publicação foi interrompida')]
summary={'production_version':'1.4.6','homolog_version':'1.4.30','publication_started':False,'application_file_changes':0,'database_changes':0,'service_restarts':0,'config_hashes_unchanged':True,'nginx_hashes_unchanged':True,'application_roots_unchanged':len(before['files']),'application_files_unchanged':sum(len(v) for v in before['files'].values()),'migrations_present':len(audit),'pcp_migrations_present':sum(r['area']=='pcp' for r in audit),'blockers':['Armação: four enabled:true production rows versus disabled release decision','CQ: live/default FCK 35 on homolog versus 25 on production and reference SQL'],'backup':backup,'candidate':frozen,'cluster_common_headroom_before':before['cluster']['common_headroom'],'cluster_common_headroom_after':after['cluster']['common_headroom'],'production_tag_created':False,'push_or_pr':False}
(O/'delivery-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
body='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Produção — publicação interrompida no checkpoint</title><style>body{font:16px/1.55 system-ui,sans-serif;color:#18324d;background:#f4f6f8;margin:0}main{max-width:1200px;margin:auto;padding:36px 24px}h1{line-height:1.15}h2{margin-top:36px}table{border-collapse:collapse;width:100%;font-size:14px;margin:16px 0;background:white}td,th{padding:10px;border:1px solid #dce2e8;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#edf2f6}code,pre{font:13px/1.5 ui-monospace,monospace;background:#e7edf2;overflow-wrap:anywhere;white-space:pre-wrap;padding:12px;display:block}.stop{padding:20px;background:#fff2d7;border-left:5px solid #b97304}a{color:#075fb5}img{width:100%;border:1px solid #ccd5dd}.muted{color:#526579}</style><main><p class="muted">20/11/2026 · publicação autorizada, condicionada ao checkpoint</p><h1>Produção permanece na 1.4.6</h1><div class="stop"><strong>A publicação foi interrompida antes de qualquer alteração na aplicação ou nos bancos de produção.</strong><p>O inventário encontrou dois estados diferentes do ambiente validado. O prompt exige parar nesse ponto. A homologação continua na candidata 1.4.30.</p></div>'''
body+='<h2>Impedimentos e proposta</h2><p><strong>Armação.</strong> O serviço de produção usa <code>pcp_unificado_teste.armacao.configuracao_unidade</code>. Os quatro registros estão habilitados desde 30/10; a homologação tem os quatro desabilitados. A decisão de manter Armação desativada não corresponde ao estado encontrado. Não executei o UPDATE.</p>'+table(['Unidade','Produção: enabled','Decisão / homologação','Ação executada'],arm_rows)
body+='<p>Proposta para sua decisão: desabilitar somente os quatro registros (IDs 1–4), com exportação SQL das linhas, transação, verificação e reversão por linha. Acrescentar explicitamente essa alteração de dados ao plano, atualizar o backup e repetir o checkpoint. Não é uma migração pendente. Nenhum serviço precisa ser reiniciado apenas por essa alteração.</p>'
body+='<p><strong>CQ / FCK.</strong> A produção tem valor e DEFAULT 25; a homologação tem valor e DEFAULT 35 em <code>public.cq_parametros.fck_mpa</code>. Os SQLs 001 e 007 prescrevem 25. A checagem inicial do CQ tinha uma lacuna na leitura de nomes de tabelas sem schema; ela foi corrigida, e a auditoria agora comprova também as cinco colunas da CQ 006. A diferença de FCK permanece registrada como configuração incompatível entre os ambientes.</p>'+table(['Configuração','Produção','Homologação','Referência SQL'],[('FCK do registro id=1',25,35,25),('DEFAULT da coluna',25,35,25)])
body+='<p>Proposta: preservar o FCK 25 da produção. Após resolver a divergência, validar a candidata em homologação com a configuração de referência e repetir as provas de certificados/PDF, sem emitir registros de teste na produção. Não alterar o FCK da produção para acompanhar a homologação.</p><p>'+a('checkpoint-live-evidence.json','Evidências reais de Armação e CQ')+' · '+a('checkpoint.json','Decisão do checkpoint')+' · '+a('runtime-configuration-discrepancies.json','Diferença estrutural do DEFAULT')+'</p>'
body+='<h2>O que ficou pronto</h2>'+table(['Etapa','Resultado'],checks)
body+='<p>O ensaio restaurou os bytes da candidata, sem apagar arquivos da homologação. O tempo de restauração até recolocar a candidata foi 25,81 s; o ciclo completo com os dois gates e as telas levou aproximadamente 45,34 s. O login por senha correta não foi exercitado: não havia credencial de teste disponível; as provas da homologação usaram sessões temporárias de contas existentes. O teste de worker usa Chrome persistente; não comprova a interface de instalação do sistema operacional nem um aparelho físico.</p><p>'+a('phase0-validation.json','Matriz de 9 perfis / 72 casos')+' · '+a('phase0-gate.txt','Gate 7/7')+' · '+a('rollback-rehearsal.json','Ensaio da reversão')+' · '+a('production-sw-before.json','Worker 1.4.6 antes da publicação')+'</p>'
body+='<h2>Pacote congelado e diferença prevista</h2>'+table(['Item','Valor'],[('Versão candidata','1.4.30'),('Arquivos no manifesto',384),('Arquivos estáticos',348),('Diferença estática','249 substituições; 62 adições; 37 idênticos'),('Backend, migrações e concessões previstas','Nenhuma: a produção já tem as estruturas e os papéis necessários'),('Reinícios e Nginx','Nenhum'),('Archive SHA-256',frozen['archive_sha256']),('Manifesto SHA-256',frozen['manifest_sha256'])])
body+='<p>O pacote exclui faixa de teste, porta 18446, configurações de homologação, tela Teste programação e user-alex nas listas master. As únicas ocorrências de “homolog” em arquivos públicos são campos de homologação de fornecedores em Suprimentos. A integração técnica de Estoque do ERP, os pools de produção e os drop-ins/eBPF de Fechamento estão fora da publicação. As rotas e o fluxo de cookie do Estoque atual não recebem patch de backend. aviso.json está com ativo:false; o Indicador geral está oculto para PCP no menu, módulo e busca.</p><p>'+a('candidate-manifest.json','Manifesto por arquivo, tamanho e SHA-256')+' · '+a('deployment-plan.json','Delta completo')+' · '+a('candidate-exclusions.json','Exclusões')+' · '+a('candidate-domain-scan.json','Varredura de ambiente')+'</p>'
body+='<h2>Migrações: estado real em produção</h2><p>As 34 referências estão presentes conforme o código de origem e os objetos do catálogo. Incluem 19 do PCP, 5 de Armação/IAM, acesso rápido, user_units, CQ 001–007 e certificados do Laboratório. Nenhuma foi aplicada. As migrações de dados já existentes não serão reexecutadas. A divergência do FCK entre ambientes não será resolvida por reaplicar cegamente uma migração.</p>'+table(['Área','Revisão / referência','Estado conforme origem','Objetos conferidos'],audit_rows)+'<p>'+a('migration-audit.json','Evidência completa: colunas, tipos, defaults, constraints, índices e hashes de origem')+' · '+a('migration-status.csv','Tabela CSV')+'</p>'
body+='<h2>Identidade real de Alex</h2>'+table(['Módulo','Identidade real','Acesso atual','Resultado'],grant_rows)+'<p>Não houve concessão nova, criação de identidade, alteração de senha ou reaproveitamento de UUID da homologação. As verificações de acesso aos oito módulos na nova versão em produção ficam pendentes até a publicação. As evidências nominais e de vínculo estão em '+a('identity-and-data-evidence.json','identidades reconciliadas')+' e '+a('deployment-plan.json','plano de publicação')+'.</p>'
body+='<h2>PostgreSQL e auditoria de preservação</h2>'+table(['Item','Antes','Após interromper'],[('max_connections',before['cluster']['max_connections'],after['cluster']['max_connections']),('Conexões client backend (inclui leitura de auditoria)',before['cluster']['client_backends'],after['cluster']['client_backends']),('Folga comum, descontadas reservas',before['cluster']['common_headroom'],after['cluster']['common_headroom']),('Arquivos da aplicação alterados pela tarefa',0,0),('Configurações systemd / Nginx alteradas',0,0),('Sessões encerradas / pools alterados',0,0)])
body+='<p>Foram reconferidos '+str(summary['application_files_unchanged'])+' arquivos em '+str(summary['application_roots_unchanged'])+' raízes: hashes idênticos. A folga é calculada como max_connections menos reservas e client backends; processos internos não consomem slots comuns. A leitura de inventário mantém sua própria conexão apenas durante a consulta. Os grupos sem processo local identificado ficam explícitos, sem atribuição presumida a um serviço.</p>'+table(['Serviço / origem','Banco','Usuário','application_name','Estado','Conexões'],connection_rows)+'<p>'+a('connections-by-service.csv','Conexões por serviço/pool e estado em CSV')+' · '+a('inventory.json','Inventário inicial')+' · '+a('inventory-after-stop.json','Auditoria após interromper')+'</p>'
body+='<h2>Backup e reversão</h2>'+table(['Item','Valor'],[('Diretório privado',backup['directory']),('Arquivo único para baixar',backup['bundle']),('Tamanho em bytes',backup['bytes']),('SHA-256',backup['sha256']),('Permissões','diretório 0700; arquivo 0600'),('Retenção mínima',backup['retain_until']),('Dumps verificados',6)])
body+='<p>Backup completo dos arquivos públicos e das árvores de Laboratório, Dosagem e Carta de traço, mais unidades, drop-ins e Nginx. O serviço histórico de Carta em /homolog/laboratorio atende a rota atual de produção na porta 13065; a homologação visual 18446 usa homolog-next, separadamente. Os seis dumps abrangem Mapa, PCP, Laboratório/CQ, Suprimentos, Qualidade e GED. Como não há concessão a fazer, o arquivo permissions-before.sql registra essa ausência; os dumps preservam todo o estado de acesso.</p><p>Comando para baixar ao seu computador:</p><pre>'+e(scp)+'</pre><p>Reversão preparada, apenas se houver publicação futura: restaura os 286 arquivos preexistentes, guarda novos arquivos em quarentena e mantém os dados. O script foi conferido em modo de verificação; não foi executado contra a produção. Não há migrações ou concessões a reverter neste delta, nem serviços a reiniciar. Para a produção atual 1.4.6, não há reversão a executar.</p><pre>'+e(rollback)+'</pre><p>'+a('backup-final.json','Comprovante de backup')+'</p>'
body+='<h2>Capturas disponíveis</h2><p>Ensaio na homologação:</p><p>'+a('rollback-1.4.29.png','Anterior: 1.4.29')+' · '+a('rollback-1.4.30.png','Candidata restaurada: 1.4.30')+'</p><p>Produção antes de qualquer publicação: '+a('production-sw-before.png','Login e perfil Chrome com worker 1.4.6')+'. As capturas da nova versão em produção, em 1440 e 390, não foram feitas porque a publicação não começou.</p><p class="muted">Nenhuma tag de produção foi criada. Sem push ou PR. Candidata e backups preservados. Trabalho interrompido no checkpoint solicitado.</p></main></html>'
body=body.replace('code,pre{font:13px/1.5 ui-monospace,monospace;background:#e7edf2;overflow-wrap:anywhere;white-space:pre-wrap;padding:12px;display:block}', 'code{font:13px/1.5 ui-monospace,monospace;background:#e7edf2;padding:2px 6px;overflow-wrap:anywhere}pre{font:13px/1.5 ui-monospace,monospace;background:#e7edf2;overflow-wrap:anywhere;white-space:pre-wrap;padding:12px;display:block}')
(O/'RELATORIO.html').write_text(body,encoding='utf-8')
print(json.dumps({'report':str(O/'RELATORIO.html'),'production_version':after['version'],'application_files_unchanged':summary['application_files_unchanged'],'blockers':len(summary['blockers']),'backups_verified':backup['dumps_verified'],'published':False}))
